class Superpower {
public:
    virtual ~Superpower() = default;
protected:
    virtual void activate() = 0;                  // the sandbox method
    void playSound(SoundId id, double volume);    // provided operations
    void spawnParticles(ParticleType t, int n);
    void move(double x, double y, double z);
};

class SkyLaunch final : public Superpower {
protected:
    void activate() override { playSound(SOUND_SPROING, 1.0); spawnParticles(PARTICLE_DUST, 10); move(0, 0, 20); }
};

