template <class Derived>
class Sandbox {
public:
    void activate() { static_cast<Derived*>(this)->activate(); }   // no vtable
protected:
    void playSound(SoundId id, double volume);                     // primitives, one copy per Derived
    void spawnParticles(ParticleType t, int n);
};

class SkyLaunch final : public Sandbox<SkyLaunch> {
    friend class Sandbox<SkyLaunch>;
    void activate() { playSound(SOUND_SPROING, 1.0); spawnParticles(PARTICLE_DUST, 10); }
};
